// -----------------------------------------------------------------------
// EDIT THIS BLOCK: it is the whole ranking policy for the project.
// Deterministic on purpose - you can explain and test every point.
// -----------------------------------------------------------------------
const PROFILE = {
  titles: ['engineer', 'developer', 'analyst', 'automation', 'backend', 'full stack', 'fullstack', 'platform', 'data', 'sre', 'devops', 'qa'],
  mustHave: ['javascript', 'typescript', 'python', 'sql', 'api', 'docker'],
  niceToHave: ['aws', 'gcp', 'azure', 'kubernetes', 'postgres', 'redis', 'n8n', 'airflow', 'llm', 'terraform', 'graphql', 'ci/cd'],
  negative: ['commission only', 'commission-based', 'unpaid', '10+ years', '12+ years', '15+ years', 'sales executive', 'sales manager', 'district manager'],
};

const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.title);
if (!rows.length) {
  return [{ json: { empty: true, note: 'nothing left to score' } }];
}

const hits = (haystack, needles) => needles.filter((n) => haystack.includes(n));

const scored = rows.map((r) => {
  const title = String(r.title || '').toLowerCase();
  const body = (title + ' ' + String(r.description || '')).toLowerCase();
  const location = String(r.location || '').toLowerCase();

  const must = hits(body, PROFILE.mustHave);
  const nice = hits(body, PROFILE.niceToHave);
  const titleHit = PROFILE.titles.filter((t) => title.includes(t));
  const negatives = hits(body, PROFILE.negative);
  const remote = /remote|anywhere|worldwide/.test(location) || /fully remote|remote-first/.test(body);

  const skillScore = Math.min(must.length / 3, 1) * 40;
  const niceScore = Math.min(nice.length / 4, 1) * 15;
  const titleScore = titleHit.length ? 20 : 0;
  const remoteScore = remote ? 10 : 0;

  let recencyScore = 0;
  if (r.posted_at) {
    const days = (Date.now() - new Date(r.posted_at).getTime()) / 86400000;
    if (!isNaN(days)) recencyScore = days <= 7 ? 15 : days <= 14 ? 10 : days <= 30 ? 5 : 0;
  }

  let score = skillScore + niceScore + titleScore + remoteScore + recencyScore;
  const reasons = [
    'skills ' + Math.round(skillScore) + '/40 (' + (must.join(', ') || 'none') + ')',
    'bonus ' + Math.round(niceScore) + '/15 (' + (nice.slice(0, 5).join(', ') || 'none') + ')',
    'title ' + titleScore + '/20',
    'remote ' + remoteScore + '/10',
    'recency ' + recencyScore + '/15',
  ];

  if (negatives.length) {
    score -= 30;
    reasons.push('penalty -30 (' + negatives.join(', ') + ')');
  }

  return {
    id: Number(r.id),
    score: Math.max(0, Math.min(100, Math.round(score))),
    reasons,
    matched: must.concat(nice).slice(0, 15),
    // Skills the JD asks for that you have not listed - your resume gap report.
    missing: PROFILE.mustHave.filter((k) => !must.includes(k)),
  };
});

return scored.map((s) => ({ json: s }));

// Single UPDATE ... FROM (VALUES ...) instead of N round trips.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.score !== undefined);
if (!rows.length) return [{ json: { rows: 0, sql: 'SELECT 1;' } }];

const q = (v) => "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
const arr = (v) => q(JSON.stringify(v || [])) + '::jsonb';

const CHUNK = 100;
const chunks = [];
for (let i = 0; i < rows.length; i += CHUNK) chunks.push(rows.slice(i, i + CHUNK));

return chunks.map((chunk) => ({
  json: {
    rows: chunk.length,
    sql:
      'UPDATE jobs AS j SET score = v.score::int, score_reasons = v.reasons::jsonb, ' +
      'matched_keywords = v.matched::jsonb, missing_keywords = v.missing::jsonb, updated_at = now() ' +
      'FROM (VALUES ' +
      chunk
        .map((r) => '(' + [r.id, Math.round(r.score), arr(r.reasons), arr(r.matched), arr(r.missing)].join(',') + ')')
        .join(',') +
      ') AS v(id, score, reasons, matched, missing) WHERE j.id = v.id::bigint;',
  },
}));

const scored = $('Score').all().map((i) => i.json).filter((r) => r && r.score !== undefined);
if (!scored.length) {
  return [{ json: { scored: 0, note: 'queue was empty' } }];
}

const avg = Math.round(scored.reduce((n, r) => n + r.score, 0) / scored.length);
const strong = scored.filter((r) => r.score >= 70).length;
const gaps = {};
for (const r of scored) for (const k of r.missing || []) gaps[k] = (gaps[k] || 0) + 1;

return [
  {
    json: {
      scored: scored.length,
      average_score: avg,
      shortlisted: strong,
      top_missing_skills: Object.entries(gaps).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k, v]) => k + ':' + v),
    },
  },
];
